<script>
const uploadDialog=document.getElementById('media-upload'), metadataDialog=document.getElementById('media-metadata');
document.querySelectorAll('[data-open-upload]').forEach(button=>button.addEventListener('click',()=>uploadDialog.showModal()));
document.querySelectorAll('[data-close-media]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
document.querySelectorAll('[data-media-edit]').forEach(button=>button.addEventListener('click',()=>{const media=JSON.parse(button.dataset.mediaEdit);const form=document.getElementById('metadata-form');form.action=`/admin/media/${media.id}`;for(const key of ['alt','credit','caption'])form.elements.namedItem(key).value=media[key]??'';document.getElementById('media-delete-form').action=`/admin/media/${media.id}`;document.querySelector('[data-metadata-preview]').src=`/media/${media.id}/480`;metadataDialog.showModal();}));
document.getElementById('media-delete-form').addEventListener('submit',event=>{if(!confirm(event.currentTarget.dataset.confirmDelete))event.preventDefault();});
@if($errors->any()) uploadDialog.showModal(); @endif
</script>
